```java
// ─── File: S3LifecycleDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.s3;

import java.util.*;
import java.util.logging.*;

public class S3LifecycleDemo {
    private static final Logger log = Logger.getLogger("S3Lifecycle");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rules: age thresholds -> storage class; final rule expires.
        LifecyclePolicy policy = new LifecyclePolicy(List.of(
                new TransitionRule(0,    "STANDARD"),
                new TransitionRule(30,   "STANDARD_IA"),
                new TransitionRule(90,   "GLACIER_FLEXIBLE"),
                new TransitionRule(365,  "GLACIER_DEEP_ARCHIVE")),
                3650 /* expire after 10 years */);

        List<S3Object> objects = List.of(
                new S3Object("2026/10/rajesh-SAV2001.pdf", 5),
                new S3Object("2026/07/priya-CUR3001.pdf", 100),
                new S3Object("2025/08/rajesh-SAV2001.pdf", 400),
                new S3Object("2016/01/old-statement.pdf", 4000));

        for (S3Object o : objects) {
            if (policy.shouldExpire(o)) {
                log.warning(() -> o.key() + " (age " + o.ageDays() + "d) -> EXPIRE (deleted, retention met)");
            } else {
                log.info(() -> o.key() + " (age " + o.ageDays() + "d) -> " + policy.targetClass(o));
            }
        }
    }
}

// ─── Would be in LifecyclePolicy.java ───
class LifecyclePolicy {
    private final List<TransitionRule> rules; // sorted by age ascending
    private final int expireAfterDays;

    LifecyclePolicy(List<TransitionRule> rules, int expireAfterDays) {
        this.rules = new ArrayList<>(rules);
        this.rules.sort(Comparator.comparingInt(TransitionRule::minAgeDays));
        this.expireAfterDays = expireAfterDays;
    }

    // The target class is the last rule whose age threshold the object has reached.
    String targetClass(S3Object o) {
        String cls = "STANDARD";
        for (TransitionRule r : rules) {
            if (o.ageDays() >= r.minAgeDays()) cls = r.storageClass();
        }
        return cls;
    }

    boolean shouldExpire(S3Object o) {
        return o.ageDays() >= expireAfterDays;
    }
}

// ─── Would be in S3Object.java ───
class S3Object {
    private final String key;
    private final int ageDays;
    S3Object(String key, int ageDays) { this.key = key; this.ageDays = ageDays; }
    String key() { return key; }
    int ageDays() { return ageDays; }
}

// ─── Would be in TransitionRule.java ───
class TransitionRule {
    private final int minAgeDays;
    private final String storageClass;
    TransitionRule(int minAgeDays, String storageClass) {
        this.minAgeDays = minAgeDays; this.storageClass = storageClass;
    }
    int minAgeDays() { return minAgeDays; }
    String storageClass() { return storageClass; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
